-- Olive Young public ranking seed captured 2026-09-27T06:26:23.709Z
-- Idempotent: source + source_key updates existing products instead of duplicating them.

begin;

create temp table oy_seed (
  source text not null,
  source_key text not null,
  source_list text not null,
  source_rank integer,
  category_hint text not null,
  brand_name_ko text not null,
  name_ko text not null,
  regular_price_krw integer,
  sale_price_krw integer,
  currency text not null,
  hero_image_url text not null,
  source_url text not null
) on commit drop;


select distinct
  'oy-' || substr(md5(brand_name_ko), 1, 16),
  brand_name_ko,
  'https://www.oliveyoung.co.kr',
  'KR',
  true
from oy_seed
on conflict (slug) do update
set name_ko = excluded.name_ko, website_url = excluded.website_url, active = true;

  channel, brand_id, category_id, item_type, name_ko, hero_image_url,
  price_krw, source, source_key, attributes, active
)
select
  'beauty',
  b.id,
  c.id,
  'product',
  s.name_ko,
  s.hero_image_url,
  coalesce(s.sale_price_krw, s.regular_price_krw),
  s.source,
  s.source_key,
  jsonb_build_object(
    'retailer', 'Olive Young',
    'source_list', s.source_list,
    'source_rank', s.source_rank,
    'regular_price_krw', s.regular_price_krw,
    'sale_price_krw', s.sale_price_krw,
    'currency', s.currency,
    'source_url', s.source_url,
    'barcode_status', 'pending_physical_scan'
  ),
  true
from oy_seed s
join public.brands b on b.slug = 'oy-' || substr(md5(s.brand_name_ko), 1, 16)
join public.categories c
  on c.channel = 'beauty'
 and c.slug = case s.category_hint
   when 'skincare' then 'skincare'
   when 'makeup' then 'makeup'
   else 'olive-young'
 end
on conflict (source, source_key) where source_key is not null and source_key <> ''
do update set
  brand_id = excluded.brand_id,
  category_id = excluded.category_id,
  name_ko = excluded.name_ko,
  hero_image_url = excluded.hero_image_url,
  price_krw = excluded.price_krw,
  attributes = excluded.attributes,
  active = true;

commit;

select
  count(*) as oliveyoung_items,
  count(*) filter (where attributes->>'barcode_status' = 'pending_physical_scan') as waiting_for_barcode
from public.catalog_items
where source = 'oliveyoung';
